for r in remote:
 b=(root/r['path']).read_bytes()
 assert len(b)==r['size'] and blob(b)==r['sha'],r['path']
derived=runpy.run_path(str(root/'verify.py'),run_name='peer_readonly')['verify']()
assert derived==json.loads((root/'VERIFIED-RESULT.json').read_bytes())
archive=(root/'original.zip').read_bytes()
meta=json.loads((root/'artifact-metadata.json').read_bytes())
assert meta['id']==10612482655 and meta['size_in_bytes']==len(archive)
assert meta['digest']=='sha256:'+sha(archive)
manifest=json.loads((root/'archive-verification.json').read_bytes())
with zipfile.ZipFile(io.BytesIO(archive)) as z:
 names=z.namelist()
 assert len(names)==len(set(names))==66
 assert set(names)=={r['path'] for r in manifest['members']}
 for n in names:
  p=PurePosixPath(n)
  assert not p.is_absolute() and '..' not in p.parts and not z.getinfo(n).is_dir()
  assert z.read(n)==(root/'raw'/n).read_bytes(),n
run=json.loads((root/'run-metadata.json').read_bytes())
job=json.loads((root/'job-metadata.json').read_bytes())['jobs']
assert len(job)==1
job=job[0]
assert run['id']==job['run_id']==meta['workflow_run']['id']==35534417441
assert job['id']==106140742308
assert run['head_sha']==job['head_sha']==meta['workflow_run']['head_sha']=='a127881cb85de4e062942a4cbe204609681f5001'
assert run['status']==job['status']=='completed'
assert run['conclusion']==job['conclusion']=='success'
bound=json.loads((root/'raw/mac-recovery-output/binding-before.json').read_bytes())
source_root=root.parent/'mac-recovery-400-prep'
for r in selected['source']:
 b=(source_root/r['path']).read_bytes()
 record=next(x for x in bound['members'] if x['path']==r['path'])
 assert blob(b)==r['sha'] and len(b)==record['bytes'] and sha(b)==record['sha256'],r['path']
